// split MPI_COMM_WORLD into per-node communicators (hybrid MPI+OpenMP placement)
MPI_Comm node_comm;
MPI_Comm_split_type(MPI_COMM_WORLD, MPI_COMM_TYPE_SHARED, 0,
                    MPI_INFO_NULL, &node_comm);
int node_rank; MPI_Comm_rank(node_comm, &node_rank);   // 0 = node leader

// 2D grid: row and column sub-communicators
int row = world_rank / ncols, col = world_rank % ncols;
MPI_Comm row_comm, col_comm;
MPI_Comm_split(MPI_COMM_WORLD, row, col, &row_comm);   // group by row
MPI_Comm_split(MPI_COMM_WORLD, col, row, &col_comm);   // group by col
```
- **Demonstrates**: `MPI_Comm_split_type` for node-local communicators (hybrid placement) and `MPI_Comm_split` for row/column decomposition.

```c
// 2D periodic Cartesian grid + halo exchange via Cart_shift
int dims[2] = {0,0}, periods[2] = {1,1};
MPI_Dims_create(nprocs, 2, dims);            // balanced factorization
MPI_Comm cart;
MPI_Cart_create(MPI_COMM_WORLD, 2, dims, periods, /*reorder=*/1, &cart);

int up, down, left, right;
MPI_Cart_shift(cart, 0, 1, &up, &down);      // neighbors along dim 0
MPI_Cart_shift(cart, 1, 1, &left, &right);   // neighbors along dim 1

MPI_Sendrecv(top_row,    n, MPI_DOUBLE, up,   0,
             bot_halo,   n, MPI_DOUBLE, down, 0, cart, MPI_STATUS_IGNORE);
```
- **Demonstrates**: `MPI_Dims_create` + `MPI_Cart_create(reorder)` for a locality-aware grid, then `MPI_Cart_shift` feeding `MPI_Sendrecv` halo exchange (boundaries auto-handled via `MPI_PROC_NULL`).

```c
// switch off fatal aborts so we can handle errors
MPI_Comm_set_errhandler(MPI_COMM_WORLD, MPI_ERRORS_RETURN);
int err = MPI_Send(buf, n, MPI_DOUBLE, dest, tag, comm);
if (err != MPI_SUCCESS) {
  char msg[MPI_MAX_ERROR_STRING]; int len;
  MPI_Error_string(err, msg, &len);
  fprintf(stderr, "MPI error: %s\n", msg);
}

// aligned cross-rank timing
MPI_Barrier(comm);                 // align ranks before timing a collective phase
double t0 = MPI_Wtime();
phase();
double dt = MPI_Wtime() - t0, dt_max;
MPI_Reduce(&dt, &dt_max, 1, MPI_DOUBLE, MPI_MAX, 0, comm);   // slowest rank
```
- **Demonstrates**: `MPI_ERRORS_RETURN` + `MPI_Error_string` for recoverable error handling, and barrier-aligned `MPI_Wtime` + max-reduce for honest cross-rank timing.

