```c
// Sessions Model: a library initializes MPI independently of main()
MPI_Session sh;
MPI_Session_init(MPI_INFO_NULL, MPI_ERRORS_RETURN, &sh);
MPI_Group wgroup;
MPI_Group_from_session_pset(sh, "mpi://WORLD", &wgroup);
MPI_Comm comm;
MPI_Comm_create_from_group(wgroup, "lib.tag", MPI_INFO_NULL,
                           MPI_ERRORS_RETURN, &comm);
/* ... library uses comm ... */
MPI_Comm_free(&comm); MPI_Group_free(&wgroup); MPI_Session_finalize(&sh);
```
- **Demonstrates**: World-Model `MPI_Init_thread` for hybrid MPI+OpenMP, and the Sessions-Model chain (`Session_init` → process set → group → communicator) for library-friendly init.

```c
// active-target (fence) one-sided accumulate
MPI_Win win;
MPI_Win_allocate(n*sizeof(double), sizeof(double), MPI_INFO_NULL,
                 comm, &base, &win);
MPI_Win_fence(0, win);                      // open epoch
MPI_Accumulate(local, n, MPI_DOUBLE, target_rank, 0, n, MPI_DOUBLE,
               MPI_SUM, win);               // atomic remote += local
MPI_Win_fence(0, win);                      // close epoch -> now complete
MPI_Win_free(&win);

// node-local shared memory window
MPI_Comm node; MPI_Comm_split_type(comm, MPI_COMM_TYPE_SHARED, 0, MPI_INFO_NULL, &node);
MPI_Win shwin; double *shptr;
MPI_Win_allocate_shared(bytes, sizeof(double), MPI_INFO_NULL, node, &shptr, &shwin);
// shptr is directly load/store-accessible across the node's ranks (with sync)
```
- **Demonstrates**: fence-synchronized atomic `MPI_Accumulate`, and a shared-memory window for direct intra-node access.

```c
// each rank writes its block of a distributed 2D array into one shared file
int gsizes[2]={NX,NY}, lsizes[2]={nx,ny}, starts[2]={x0,y0};
MPI_Datatype filetype;
MPI_Type_create_subarray(2, gsizes, lsizes, starts, MPI_ORDER_C, MPI_DOUBLE, &filetype);
MPI_Type_commit(&filetype);

MPI_File fh;
MPI_File_open(comm, "field.dat", MPI_MODE_CREATE|MPI_MODE_WRONLY, info, &fh);
MPI_File_set_view(fh, 0, MPI_DOUBLE, filetype, "native", info);
MPI_File_write_all(fh, local, nx*ny, MPI_DOUBLE, MPI_STATUS_IGNORE);  // collective
MPI_File_close(&fh);
MPI_Type_free(&filetype);
```
- **Demonstrates**: the canonical distributed-array write — a `subarray` filetype gives each rank its file region, and **`MPI_File_write_all`** (collective) lets the implementation aggregate for throughput.

```c
// PMPI wrapper: count and time every MPI_Send (a tool/profiling library)
static double send_time = 0; static long send_count = 0;
int MPI_Send(const void *buf, int n, MPI_Datatype t, int dest, int tag, MPI_Comm c) {
  double t0 = PMPI_Wtime();
  int rc = PMPI_Send(buf, n, t, dest, tag, c);   // delegate to the real impl
  send_time += PMPI_Wtime() - t0; send_count++;
  return rc;
}
```
- **Demonstrates**: the PMPI interception pattern — redefine `MPI_Send`, measure, then call `PMPI_Send`; linked transparently via weak symbols, no app recompile.
